import type {CompiledLayeredSchema} from "../data-layer-layered-schema.js";
import {layeredConditionMatches,layeredPropertyPaths,resolveConditionalLayeredSchema} from "./conditional-rules.js";

type LayerValidationIssue={path:string;code:"REQUIRED"|"FORBIDDEN"|"TYPE"|"ALLOWED_VALUE"|"PATTERN"|"MINIMUM"|"MAXIMUM"|"MIN_ITEMS"|"MAX_ITEMS"|"EXPECTED_VALUE";severity:"error";expected:unknown;actual:unknown;provenance:string};
const clone=<T>(value:T):T=>structuredClone(value);
const same=(left:unknown,right:unknown):boolean=>JSON.stringify(left)===JSON.stringify(right);
const valueAt=(payload:Record<string,unknown>,path:string):unknown=>path.split("/").filter(Boolean).reduce<unknown>((value,key)=>value&&typeof value==="object"?(value as Record<string,unknown>)[key]:undefined,payload);
const typeMatches=(value:unknown,type:string):boolean=>type==="array"?Array.isArray(value):type==="null"?value===null:type==="integer"?Number.isInteger(value):type==="object"?Boolean(value)&&typeof value==="object"&&!Array.isArray(value):typeof value===type;
const pushIssue=(issues:LayerValidationIssue[],targetName:string,path:string,property:Record<string,unknown>,actual:unknown,code:LayerValidationIssue["code"],expected:unknown):void=>{issues.push({path,code,severity:"error",expected:clone(expected),actual:clone(actual),provenance:String(property.expectedContributor??targetName)});};
const validateProperty=(issues:LayerValidationIssue[],targetName:string,path:string,property:Record<string,unknown>,payload:Record<string,unknown>,pathsByDefinition:Map<string,string>):void=>{const actual=valueAt(payload,path),condition=layeredConditionMatches(property.condition as Record<string,unknown>|undefined,payload,pathsByDefinition);if(property.presence==="required"&&condition&&actual===undefined){pushIssue(issues,targetName,path,property,actual,"REQUIRED","present");return;}if(property.presence==="forbidden"&&condition&&actual!==undefined){pushIssue(issues,targetName,path,property,actual,"FORBIDDEN","absent");return;}if(actual===undefined)return;if(property.type&& !typeMatches(actual,String(property.type)))pushIssue(issues,targetName,path,property,actual,"TYPE",property.type);if(Array.isArray(property.allowedValues)&&!property.allowedValues.some((candidate)=>same(candidate,actual)))pushIssue(issues,targetName,path,property,actual,"ALLOWED_VALUE",property.allowedValues);if(Array.isArray(property.patterns)&&!property.patterns.every((pattern)=>new RegExp(String(pattern)).test(String(actual))))pushIssue(issues,targetName,path,property,actual,"PATTERN",property.patterns);if(typeof property.minimum==="number"&&typeof actual==="number"&&actual<property.minimum)pushIssue(issues,targetName,path,property,actual,"MINIMUM",property.minimum);if(typeof property.maximum==="number"&&typeof actual==="number"&&actual>property.maximum)pushIssue(issues,targetName,path,property,actual,"MAXIMUM",property.maximum);if(typeof property.minItems==="number"&&Array.isArray(actual)&&actual.length<property.minItems)pushIssue(issues,targetName,path,property,actual,"MIN_ITEMS",property.minItems);if(typeof property.maxItems==="number"&&Array.isArray(actual)&&actual.length>property.maxItems)pushIssue(issues,targetName,path,property,actual,"MAX_ITEMS",property.maxItems);if(property.expectedValue!==undefined&&!same(actual,property.expectedValue))pushIssue(issues,targetName,path,property,actual,"EXPECTED_VALUE",property.expectedValue);};
export function validateLayeredObservation(target:{targetId:string;targetName:string;revision:number;compiled:CompiledLayeredSchema},payload:Record<string,unknown>){const effective=resolveConditionalLayeredSchema(target.compiled,payload),issues:LayerValidationIssue[]=[],pathsByDefinition=layeredPropertyPaths(effective);for(const[path,property]of Object.entries(effective.properties))validateProperty(issues,target.targetName,path,property as unknown as Record<string,unknown>,payload,pathsByDefinition);return{selectedTargetId:target.targetId,selectedTargetName:target.targetName,effectiveSchemaRevision:target.revision,status:effective.status,conflicts:effective.conflicts,issues,provenance:effective.provenance};}
